/* Easy window controls; project resources live in Safari. */
(() => {
const close=document.createElement('button');close.id='finder-close-easy';close.className='easy-window-close';close.innerHTML='Close <span>×</span>';close.setAttribute('aria-label','Close Finder window');close.onclick=()=>closeFinder();document.querySelector('.window-bar').append(close);
const hint=document.createElement('button');hint.className='desktop-gallery-hint';hint.textContent='Explore everything in Safari ↗';hint.onclick=()=>window.openSafari();document.querySelector('.workspace').append(hint);
const shelf=document.createElement('nav');shelf.className='easy-window-switcher';shelf.setAttribute('aria-label','Open windows');shelf.hidden=true;document.querySelector('#desktop').append(shelf);
function sync(){const windows=[{id:'finder',label:document.querySelector('#window-title').textContent},{id:'portfolio-safari',label:'Safari'}].filter(w=>document.getElementById(w.id)?.open);shelf.hidden=!windows.length;shelf.innerHTML=windows.map(w=>`<div><button data-easy-window="${w.id}">${w.id==='finder'?'▣':'◈'} ${w.label.replace(/[<>]/g,'')} <span>Open</span></button><button data-easy-close="${w.id}" aria-label="Close ${w.id==='finder'?'Finder':'Safari'}">×</button></div>`).join('');}
shelf.onclick=e=>{const c=e.target.closest('[data-easy-close]'),w=e.target.closest('[data-easy-window]');if(c)document.querySelector(c.dataset.easyClose==='finder'?'#finder-close-easy':'#safari-close-window').click();if(w){const el=document.getElementById(w.dataset.easyWindow);window.dispatchEvent(new CustomEvent('portfolio:desktop-window',{detail:{app:w.dataset.easyWindow==='finder'?'finder':'safari'}}));el.querySelector('button').focus()}};
for(const id of ['finder','portfolio-safari'])new MutationObserver(sync).observe(document.getElementById(id),{attributes:true,attributeFilter:['open']});new MutationObserver(sync).observe(document.getElementById('window-title'),{childList:true});
document.querySelector('#finder').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='w'){e.preventDefault();e.stopPropagation();closeFinder()}});
})();
